export function debounce<T extends (...args: any[]) => any>(
  fn: T,
  wait?: number,
): (...args: Parameters<T>) => void {
  // 浏览器中 setTimeout 返回的是 number
  // 而 NodeJs 中返回的是 NodeJs.Timeout
  let timeout: ReturnType<typeof setTimeout>
  return debounced

  function debounced(this: unknown, ...args: Parameters<T>): void {
    if (timeout) clearTimeout(timeout)
    const self = this
    timeout = setTimeout(() => fn.apply(self, args), wait)
  }
}

export function debounce<T extends (...args: any[]) => any>(
  fn: T,
  wait?: number,
): (...args: Parameters<T>) => ReturnType<T> | void {
  let timeout: ReturnType<typeof setTimeout>
  let lastResult: ReturnType<T> | undefined
  return debounced

  function debounced(...args: Parameters<T>): ReturnType<T> | void {
    if (timeout) clearTimeout(timeout)

    const self = this
    timeout = setTimeout(function () {
      lastResult = fn.apply(self, args)
    }, wait)
    return lastResult
  }
}

export function throttle<T extends (...args: any[]) => any>(
  fn: T,
  wait?: number,
): (...args: Parameters<T>) => void {
  let timeout: ReturnType<typeof setTimeout> | null
  return throttled

  function throttled(...args: Parameters<T>): void {
    if (timeout) return

    const self = this
    timeout = setTimeout(function () {
      fn.apply(self, args)
      timeout = null
    }, wait)
  }
}

export function throttle<T extends (...args: any[]) => any>(
  fn: T,
  wait?: number,
): (...args: Parameters<T>) => ReturnType<T> | void {
  let timeout: ReturnType<typeof setTimeout> | null
  let lastResult: ReturnType<T> | undefined
  return throttled

  function throttled(...args: Parameters<T>): ReturnType<T> | void {
    if (timeout) return lastResult

    const self = this
    timeout = setTimeout(function () {
      lastResult = fn.apply(self, args)
      timeout = null
    }, wait)
  }
}
